INSERT INTO properties (id, name, city, address, category, price, capacity, bedrooms, bathrooms, description, amenities, image_url, featured, active) VALUES
 (1,'The Waterfront Haven','Kuching','Kuching Waterfront, Sarawak','Hotel',268,2,1,1,'Wake up to riverside views in the heart of Kuching. A calm, thoughtfully designed space for city explorers.','["Wi-Fi", "Air conditioning", "River view", "Breakfast"]'::jsonb,'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=85',TRUE,TRUE),
 (2,'Rainforest Hideaway Villa','Kuching','Santubong, Sarawak','Homestay',420,6,3,2,'A quiet tropical escape with generous gathering spaces and a lush, green setting.','["Wi-Fi", "Parking", "Kitchen", "Garden"]'::jsonb,'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=85',TRUE,TRUE),
 (3,'Skyline Suites KL','Kuala Lumpur','Bukit Bintang, Kuala Lumpur','Apartment',345,4,2,2,'Contemporary city living near shopping, food and cultural attractions.','["Wi-Fi", "City view", "Kitchen", "Pool"]'::jsonb,'https://images.unsplash.com/photo-1564501049412-61c2a3083791?auto=format&fit=crop&w=1200&q=85',TRUE,TRUE),
 (4,'Seabreeze Retreat','Kota Kinabalu','Tanjung Aru, Sabah','Resort',510,4,2,2,'Relax by the coast with bright interiors and refreshing sea breezes.','["Wi-Fi", "Pool", "Breakfast", "Sea view"]'::jsonb,'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1200&q=85',TRUE,TRUE),
 (5,'Heritage Lane Stay','George Town','George Town, Penang','Homestay',218,3,2,1,'A cozy heritage-inspired base for discovering the creative streets of Penang.','["Wi-Fi", "Air conditioning", "Kitchen"]'::jsonb,'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=85',FALSE,TRUE),
 (6,'The Garden Loft','Johor Bahru','Mount Austin, Johor Bahru','Apartment',240,4,2,2,'A welcoming modern loft with easy access to cafés and local attractions.','["Wi-Fi", "Parking", "Kitchen"]'::jsonb,'https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1200&q=85',FALSE,TRUE),
 (7,'Highland Morning Inn','Cameron Highlands','Tanah Rata, Pahang','Hotel',195,2,1,1,'Cool mountain air, warm comforts and a restful setting for your highland getaway.','["Wi-Fi", "Breakfast", "Parking"]'::jsonb,'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1200&q=85',FALSE,TRUE),
 (8,'Coastal Nest Bintulu','Bintulu','Tanjung Batu, Bintulu, Sarawak','Homestay',185,5,2,1,'A comfortable family stay near the beach, with space to unwind together.','["Wi-Fi", "Kitchen", "Parking", "Air conditioning"]'::jsonb,'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=85',FALSE,TRUE),
 (9,'Lakeside Leisure Hotel','Miri','Marina Bay, Miri, Sarawak','Hotel',225,2,1,1,'An easygoing city stay with spacious rooms and a relaxed atmosphere.','["Wi-Fi", "Air conditioning", "Parking", "Gym"]'::jsonb,'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=85',FALSE,TRUE),
 (10,'Tanjung Rhu Sunset Resort','Langkawi','Tanjung Rhu, Langkawi, Kedah','Resort',435,4,2,1,'A peaceful island-inspired retreat concept with warm, coastal styling and relaxed family stays.','["Wi-Fi", "Pool", "Breakfast", "Sea view", "Air conditioning"]'::jsonb,'https://images.unsplash.com/photo-1657463076216-8b1d12e8446d?auto=format&fit=crop&w=1200&q=85',TRUE,TRUE),
 (11,'Pantai Cenang Bay Hotel','Langkawi','Pantai Cenang, Langkawi, Kedah','Hotel',285,2,1,1,'An easygoing island base concept near the shore, with comfortable rooms and essential facilities.','["Wi-Fi", "Air conditioning", "Breakfast", "Parking", "Sea view"]'::jsonb,'https://images.unsplash.com/photo-1665988178224-8570ec282bd2?auto=format&fit=crop&w=1200&q=85',TRUE,TRUE)
