-- Seed 11 fictional demonstration stays, 25 bookable room types and their unique representative images.
-- Photos are licensed/illustrative references, NOT verified real property galleries.
ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('properties','id'),(SELECT MAX(id) FROM properties));
ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('room_types','id'),(SELECT MAX(id) FROM room_types));
ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('property_photos','id'),(SELECT MAX(id) FROM property_photos));
